-- Compiled original saved-action first-save carrier; use only the reviewed migration/test procedure.
-- Only TWO existing original function bodies change; no new signature or grants.
-- All nine released saved-email source/metadata prerequisites are checked first.
DO $exp03_saved_action$
DECLARE definitions jsonb := $action_definitions$[{"acl":"{postgres=X/postgres,service_role=X/postgres}","owner":"postgres","definer":true,"full_md5":"267864f19bb170dd1a36f8d31878d1d2","settings":["search_path=pg_catalog, public"],"signature":"prepare_comms_email_send(uuid,uuid,uuid,uuid,text,uuid,text,text,text,text,text,jsonb,jsonb)","definition":"CREATE OR REPLACE FUNCTION public.prepare_comms_email_send(_actor_user_id uuid, _expected_tenant_id uuid, _operation_id uuid, _contact_id uuid, _recipient text, _connector_id uuid, _from_address text, _subject text, _body_text text, _body_html text, _content_digest text, _command jsonb, _governance jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\nDECLARE m public.messages%ROWTYPE; c public.channel_connectors%ROWTYPE; b jsonb;\n _uuid constant text:='^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';\n _approval text; ap public.paige_pending_approvals%ROWTYPE; _act public.paige_actions%ROWTYPE;\n _live text; _cited text; _constraint text; _action_id uuid;\n agreement_source jsonb;\n _draft_source jsonb; _source_message public.messages%ROWTYPE;\n _source_connector public.channel_connectors%ROWTYPE; _source_version timestamptz;\nBEGIN\n PERFORM public._comms_email_actor(_actor_user_id,_expected_tenant_id);\n PERFORM public._comms_email_governance(_actor_user_id,_expected_tenant_id,_governance);\n IF _operation_id IS NULL THEN RAISE EXCEPTION 'COMMS_EMAIL_CONTENT_INVALID' USING ERRCODE='22023'; END IF;\n _draft_source:=_governance->'draft_source';\n IF _draft_source IS NOT NULL THEN\n  IF jsonb_typeof(_draft_source) IS DISTINCT FROM 'object'\n   OR NOT (_draft_source ?& ARRAY['message_id','updated_at'])\n   OR (SELECT count(*) FROM jsonb_object_keys(_draft_source))<>2\n   OR jsonb_typeof(_draft_source->'message_id') IS DISTINCT FROM 'string'\n   OR jsonb_typeof(_draft_source->'updated_at') IS DISTINCT FROM 'string'\n   OR coalesce(_draft_source->>'message_id','') !~ _uuid\n   OR coalesce(_draft_source->>'updated_at','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$'\n  THEN RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_SOURCE_INVALID' USING ERRCODE='22023'; END IF;\n  BEGIN _source_version:=(_draft_source->>'updated_at')::timestamptz;\n  EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN\n   RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_SOURCE_INVALID' USING ERRCODE='22023';\n  END;\n END IF;\n -- (6) The drafted reply this send answers, from the door's server-built governance record. NULL = none.\n _approval:=nullif(lower(btrim(_governance->>'approval_id')),'');\n IF _approval IS NOT NULL AND _approval !~ _uuid THEN RAISE EXCEPTION 'COMMS_EMAIL_CONTENT_INVALID' USING ERRCODE='22023'; END IF;\n PERFORM pg_advisory_xact_lock(hashtextextended(_operation_id::text,32847));\n\n SELECT * INTO m FROM public.messages WHERE meta#>>'{comms_email_binding,operation_id}'=_operation_id::text;\n IF FOUND THEN\n  b:=m.meta->'comms_email_binding';\n  IF m.tenant_id IS DISTINCT FROM _expected_tenant_id OR b->>'actor_user_id' IS DISTINCT FROM _actor_user_id::text\n   OR b->'command' IS DISTINCT FROM _command OR b->>'content_digest' IS DISTINCT FROM _content_digest\n   OR lower(b->>'approval_id') IS DISTINCT FROM _approval\n   OR b#>'{governance,draft_source}' IS DISTINCT FROM _draft_source THEN\n   RAISE EXCEPTION 'COMMS_EMAIL_REPLAY_MISMATCH' USING ERRCODE='22023';\n  END IF;\n  IF _governance->>'purpose'='agreement_signature_request'\n   AND b->'governance' IS DISTINCT FROM _governance THEN\n   RAISE EXCEPTION 'COMMS_EMAIL_REPLAY_MISMATCH' USING ERRCODE='22023'; END IF;\n  RETURN jsonb_build_object('ok',true,'replayed',true,'state',b->>'state','message_id',m.id);\n END IF;\n\n -- Lock the original saved row, never INSERT a substitute or relabel a commercial binding.\n IF _draft_source IS NOT NULL THEN\n  IF _governance->>'purpose'='agreement_signature_request' THEN\n   RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_OWNED_FLOW_REQUIRED' USING ERRCODE='42501'; END IF;\n  SELECT * INTO _source_message FROM public.messages\n   WHERE id=(_draft_source->>'message_id')::uuid AND tenant_id=_expected_tenant_id FOR UPDATE;\n  IF _source_message.id IS NULL OR _source_message.channel_type IS DISTINCT FROM 'email'\n   OR _source_message.direction IS DISTINCT FROM 'outbound' OR _source_message.status IS DISTINCT FROM 'draft'\n   OR _source_message.contact_id IS DISTINCT FROM _contact_id OR _source_message.provider_message_id IS NOT NULL\n   OR _source_message.meta ?| ARRAY['comms_email_binding','sales_invoice_binding','growth_sequence_binding','email_campaign_binding']\n  THEN RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_SOURCE_UNAVAILABLE' USING ERRCODE='42501'; END IF;\n  IF _source_message.updated_at IS DISTINCT FROM _source_version THEN\n   RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_SOURCE_CHANGED' USING ERRCODE='40001'; END IF;\n  -- Changing From must not turn another person's personal source into a shared draft.\n  SELECT * INTO _source_connector FROM public.channel_connectors\n   WHERE id=_source_message.connector_id AND tenant_id=_expected_tenant_id FOR SHARE;\n  IF _source_connector.id IS NULL OR _source_connector.active IS DISTINCT FROM true\n   OR _source_connector.status IS DISTINCT FROM 'active' OR _source_connector.channel_type IS DISTINCT FROM 'email'\n   OR NOT coalesce(_source_connector.mailbox_class='shared_support'\n    OR (_source_connector.mailbox_class='personal' AND _source_connector.mailbox_owner_user_id=_actor_user_id),false)\n  THEN RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_SOURCE_UNAVAILABLE' USING ERRCODE='42501'; END IF;\n  IF _source_connector.mailbox_class='personal'\n   AND _connector_id IS DISTINCT FROM _source_message.connector_id THEN\n   RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_OWNED_FLOW_REQUIRED' USING ERRCODE='42501';\n  END IF;\n END IF;\n\n -- ORIGINAL agreement lock precedes its child message, including distinct\n -- transport intents. A lost acknowledgement is inspected, never a new send.\n IF _governance->>'purpose'='agreement_signature_request' THEN\n  agreement_source:=private.e04_agreement_email_origin(_actor_user_id,_expected_tenant_id,_governance,true);\n  IF _operation_id::text IS DISTINCT FROM agreement_source->>'operation_id'\n   OR _contact_id::text IS DISTINCT FROM agreement_source->>'client_id'\n   OR _recipient IS DISTINCT FROM agreement_source#>>'{message,to}'\n   OR _subject IS DISTINCT FROM agreement_source#>>'{message,subject}'\n   OR _body_text IS DISTINCT FROM agreement_source#>>'{message,body_text}'\n   OR _body_html IS DISTINCT FROM agreement_source#>>'{message,body_html}'\n   OR _connector_id::text IS DISTINCT FROM agreement_source#>>'{sender,connector_id}'\n   OR _from_address IS DISTINCT FROM agreement_source#>>'{sender,from_address}'\n   OR _command IS DISTINCT FROM agreement_source->'command' THEN\n   RAISE EXCEPTION 'COMMS_EMAIL_AGREEMENT_SOURCE_CHANGED' USING ERRCODE='40001'; END IF;\n  IF EXISTS(SELECT 1 FROM public.messages previous\n    WHERE previous.tenant_id=_expected_tenant_id\n     AND previous.meta#>>'{comms_email_binding,governance,purpose}'='agreement_signature_request'\n     AND previous.meta#>>'{comms_email_binding,governance,agreement_work_id}'=agreement_source->>'work_id'\n     AND previous.meta#>>'{comms_email_binding,governance,signer_id}'=agreement_source#>>'{signer,id}') THEN\n   RAISE EXCEPTION 'COMMS_EMAIL_AGREEMENT_INTENT_ALREADY_RECORDED' USING ERRCODE='55000'; END IF;\n ELSE\n -- The command is the canonical approved shape; its fields must be the ones being prepared.\n IF _command IS NULL OR jsonb_typeof(_command)<>'object' OR _command->>'action' IS DISTINCT FROM 'comms.email_send'\n  OR _command->>'contact_id' IS DISTINCT FROM _contact_id::text OR _command->>'subject' IS DISTINCT FROM _subject\n  OR _command->>'body' IS DISTINCT FROM _body_text\n  OR (_command->>'connector_id' IS NOT NULL AND _command->>'connector_id' IS DISTINCT FROM _connector_id::text) THEN\n  RAISE EXCEPTION 'COMMS_EMAIL_CONTENT_INVALID' USING ERRCODE='22023';\n END IF;\n\n END IF;\n\n -- (6) One live send per reply approval. The approval row is locked, so two confirms of different\n -- operations for the same reply serialize here; the second sees the first's send and is refused.\n IF _approval IS NOT NULL THEN\n  SELECT * INTO ap FROM public.paige_pending_approvals WHERE id=_approval::uuid FOR UPDATE;\n  BEGIN _action_id:=nullif(btrim(ap.metadata->>'action_id'),'')::uuid;\n  EXCEPTION WHEN invalid_text_representation THEN _action_id:=NULL; END;\n  -- PPA -> exact canonical action. Lock every backlink deterministically before proving uniqueness.\n  PERFORM 1 FROM public.paige_actions a WHERE a.approval_id=ap.id ORDER BY a.id FOR UPDATE;\n  IF ap.id IS NOT NULL AND _action_id IS NOT NULL THEN\n   SELECT * INTO _act FROM public.paige_actions a\n    WHERE a.id=_action_id AND a.approval_id=ap.id AND a.tenant_id=ap.tenant_id;\n  END IF;\n  IF ap.id IS NULL OR ap.tenant_id IS DISTINCT FROM _expected_tenant_id\n   OR _act.id IS NULL OR (_act.action_kind NOT IN ('owner.lead_followup','client.followup','owner.followup_email') AND NOT coalesce(_act.action_kind='comms-draft-reply' AND _draft_source IS NOT NULL\n    AND _source_message.id::text=_draft_source->>'message_id' AND _source_message.action_id=_act.id\n    AND _source_message.meta->>'source'='comms-draft-reply'\n    AND coalesce(_act.payload->>'channel_type','email')='email',false)) OR _act.contact_id IS DISTINCT FROM _contact_id\n   OR (ap.contact_id IS NOT NULL AND ap.contact_id IS DISTINCT FROM _contact_id)\n   OR (SELECT count(*) FROM public.paige_actions a WHERE a.approval_id=ap.id)<>1\n   OR NOT EXISTS (SELECT 1 FROM public.paige_action_kinds k WHERE k.slug=_act.action_kind AND k.executor='send_via_approval') THEN\n   RAISE EXCEPTION 'COMMS_EMAIL_APPROVAL_INVALID' USING ERRCODE='42501';\n  END IF;\n  IF ap.status IN ('approved','sent') THEN RAISE EXCEPTION 'COMMS_EMAIL_APPROVAL_ALREADY_SENT' USING ERRCODE='55000'; END IF;\n  IF ap.status IS DISTINCT FROM 'pending' THEN RAISE EXCEPTION 'COMMS_EMAIL_APPROVAL_NOT_PENDING' USING ERRCODE='55000'; END IF;\n\n  IF ap.metadata ? 'comms_email_draft' AND (_draft_source IS NULL\n   OR ap.metadata#>>'{comms_email_draft,message_id}' IS DISTINCT FROM _source_message.id::text) THEN\n   RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_OWNED_FLOW_REQUIRED' USING ERRCODE='42501';END IF;\n  IF _act.status IS NULL OR _act.status NOT IN ('drafted','pending_approval') THEN\n   RAISE EXCEPTION 'COMMS_EMAIL_ORIGIN_NOT_SENDABLE' USING ERRCODE='55000';\n  END IF;\n  -- A send prepared for this approval that has not failed or been refused …\n  SELECT o.meta#>>'{comms_email_binding,state}' INTO _live FROM public.messages o\n   WHERE o.meta ? 'comms_email_binding' AND lower(o.meta#>>'{comms_email_binding,approval_id}')=_approval\n     AND coalesce(o.meta#>>'{comms_email_binding,state}','') NOT IN ('failed','refused')\n   ORDER BY (o.meta#>>'{comms_email_binding,state}'='provider_accepted') DESC LIMIT 1;\n  -- … or the send the approval itself cites (metadata.governed_send), whatever it was prepared for.\n  IF _live IS NULL THEN\n   _cited:=lower(btrim(ap.metadata#>>'{governed_send,operation_id}'));\n   IF _cited ~ _uuid THEN\n    SELECT o.meta#>>'{comms_email_binding,state}' INTO _live FROM public.messages o\n     WHERE o.meta ? 'comms_email_binding' AND o.meta#>>'{comms_email_binding,operation_id}'=_cited\n       AND o.tenant_id=_expected_tenant_id AND coalesce(o.meta#>>'{comms_email_binding,state}','') NOT IN ('failed','refused');\n   END IF;\n  END IF;\n  IF _live='provider_accepted' THEN RAISE EXCEPTION 'COMMS_EMAIL_APPROVAL_ALREADY_SENT' USING ERRCODE='55000'; END IF;\n  IF _live IS NOT NULL THEN RAISE EXCEPTION 'COMMS_EMAIL_APPROVAL_SEND_IN_PROGRESS' USING ERRCODE='55000'; END IF;\n END IF;\n\n\n -- A saved action-owned draft must use its ORIGINAL already-validated reply approval.\n IF _draft_source IS NOT NULL AND _source_message.action_id IS DISTINCT FROM _act.id THEN\n  RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_OWNED_FLOW_REQUIRED' USING ERRCODE='42501'; END IF;\n PERFORM 1 FROM public.clients WHERE id=_contact_id AND tenant_id=_expected_tenant_id FOR SHARE;\n IF NOT FOUND THEN RAISE EXCEPTION 'COMMS_EMAIL_CONTACT_NOT_IN_WORKSPACE' USING ERRCODE='42501'; END IF;\n -- An approved business/witness signer belongs to the original agreement;\n -- it is not manufactured as another client contact method.\n IF agreement_source IS NULL THEN\n IF _recipient IS NULL OR _recipient IS DISTINCT FROM lower(btrim(_recipient)) OR length(_recipient)>320\n  OR NOT EXISTS (SELECT 1 FROM public.client_contact_methods cm WHERE cm.tenant_id=_expected_tenant_id AND cm.client_id=_contact_id\n   AND cm.kind='email' AND lower(btrim(cm.value))=_recipient) THEN\n  RAISE EXCEPTION 'COMMS_EMAIL_RECIPIENT_CHANGED' USING ERRCODE='40001';\n END IF;\n\n END IF;\n\n SELECT * INTO c FROM public.channel_connectors WHERE id=_connector_id AND tenant_id=_expected_tenant_id FOR SHARE;\n IF c.id IS NULL OR c.active IS DISTINCT FROM true OR c.status IS DISTINCT FROM 'active' OR c.channel_type IS DISTINCT FROM 'email'\n  OR c.provider IS NULL OR c.provider NOT IN ('resend','gmail','smtp','sendgrid') OR coalesce(length(btrim(c.from_address)),0)=0\n  OR _from_address IS NULL OR lower(btrim(c.from_address)) IS DISTINCT FROM lower(btrim(_from_address))\n  OR NOT coalesce(c.mailbox_class='shared_support'\n    OR (c.mailbox_class='personal' AND c.mailbox_owner_user_id=_actor_user_id),false) THEN\n  RAISE EXCEPTION 'COMMS_EMAIL_SENDER_CHANGED' USING ERRCODE='40001';\n END IF;\n -- PAIGE Email (SendGrid): a connector row alone is never proof of sender identity (a workspace\n -- admin can write one). The From's domain must carry SendGrid verification facts that only the\n -- verification service can write (guard_tenant_email_domain_sendgrid_facts, 20271031000100).\n IF c.provider='sendgrid' AND NOT public._comms_email_sendgrid_sender_verified(_expected_tenant_id,c.from_address) THEN\n  RAISE EXCEPTION 'COMMS_EMAIL_SENDER_UNVERIFIED' USING ERRCODE='42501';\n END IF;\n\n IF _subject IS NULL OR length(btrim(_subject))=0 OR length(_subject)>200 OR _subject ~ E'[\\r\\n]'\n  OR _body_text IS NULL OR length(btrim(_body_text))=0 OR length(_body_text)>10000\n  OR _body_html IS NULL OR length(_body_html)=0 OR length(_body_html)>100000 THEN\n  RAISE EXCEPTION 'COMMS_EMAIL_CONTENT_INVALID' USING ERRCODE='22023';\n END IF;\n IF _content_digest IS DISTINCT FROM encode(extensions.digest(convert_to(_recipient||E'\\n'||_connector_id::text||E'\\n'||_subject||E'\\n'||_body_text,'UTF8'),'sha256'),'hex') THEN\n  RAISE EXCEPTION 'COMMS_EMAIL_DIGEST_MISMATCH' USING ERRCODE='22023';\n END IF;\n\n\n -- An earlier identical send whose outcome is not known must be reconciled, never re-sent.\n IF EXISTS (SELECT 1 FROM public.messages o WHERE o.tenant_id=_expected_tenant_id AND o.meta ? 'comms_email_binding'\n   AND o.meta#>>'{comms_email_binding,recipient}'=_recipient AND o.meta#>>'{comms_email_binding,content_digest}'=_content_digest\n   AND o.meta#>>'{comms_email_binding,state}' IN ('dispatching','unknown')) THEN\n  RAISE EXCEPTION 'COMMS_EMAIL_RECONCILIATION_REQUIRED' USING ERRCODE='55000';\n END IF;\n\n b:=jsonb_build_object('operation_id',_operation_id::text,'tenant_id',_expected_tenant_id,'actor_user_id',_actor_user_id,\n  'contact_id',_contact_id,'recipient',_recipient,'connector_id',_connector_id,'from_address',lower(btrim(c.from_address)),\n  'provider',c.provider,'subject',_subject,'body_text',_body_text,'body_html',_body_html,'content_digest',_content_digest,\n  'command',_command,'governance',_governance,'state','prepared','attempts',0,'prepared_at',now(),'claimed_at',NULL,\n  'finalized_at',NULL,'provider_message_id',NULL,'outcome_reason',NULL,'approval_id',_approval,'origin_action_id',_act.id,'origin_action_kind',_act.action_kind);\n BEGIN\n  IF _draft_source IS NOT NULL THEN\n   UPDATE public.messages SET connector_id=_connector_id,\n    recipients=CASE WHEN _source_message.recipients->0->>'address'=_recipient AND jsonb_array_length(_source_message.recipients)=1\n      THEN _source_message.recipients ELSE jsonb_build_array(jsonb_build_object('address',_recipient)) END,\n    sender=CASE WHEN _source_message.sender->>'address'=lower(btrim(c.from_address))\n      THEN _source_message.sender ELSE jsonb_build_object('address',lower(btrim(c.from_address))) END,\n    subject=_subject,body_text=_body_text,body_html=_body_html,attachments='[]'::jsonb,\n    meta=coalesce(_source_message.meta,'{}'::jsonb)||jsonb_build_object('comms_email_binding',b)\n    WHERE id=_source_message.id AND tenant_id=_expected_tenant_id RETURNING * INTO m;\n   IF NOT FOUND THEN RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_SOURCE_CHANGED' USING ERRCODE='40001'; END IF;\n  ELSE\n  INSERT INTO public.messages(tenant_id,contact_id,connector_id,thread_key,channel_type,direction,status,recipients,sender,subject,body_text,body_html,meta)\n  VALUES(_expected_tenant_id,_contact_id,_connector_id,'contact:'||_expected_tenant_id::text||':'||_contact_id::text,'email','outbound','draft',\n   jsonb_build_array(jsonb_build_object('address',_recipient)),jsonb_build_object('address',lower(btrim(c.from_address))),\n   _subject,_body_text,_body_html,jsonb_build_object('source','comms-email-command','comms_email_binding',b))\n  RETURNING * INTO m;\n  END IF;\n EXCEPTION WHEN unique_violation THEN\n  GET STACKED DIAGNOSTICS _constraint = CONSTRAINT_NAME;\n  IF _constraint='messages_comms_email_approval_live' THEN\n   RAISE EXCEPTION 'COMMS_EMAIL_APPROVAL_SEND_IN_PROGRESS' USING ERRCODE='55000';\n  END IF;\n  RAISE;\n END;\n RETURN jsonb_build_object('ok',true,'replayed',false,'state','prepared','message_id',m.id);\nEND $function$\n","before_md5":"7e93cb7be01f5bbe37ae3e70d94aac5d"},{"acl":"{postgres=X/postgres,service_role=X/postgres}","owner":"postgres","definer":true,"full_md5":"54702dc2c19f34199b3a3de0f3c3a48a","settings":["search_path=pg_catalog, public"],"signature":"save_comms_email_draft(uuid,uuid,uuid,uuid,timestamp with time zone,uuid,uuid,text,text,text,jsonb,timestamp with time zone,uuid)","definition":"CREATE OR REPLACE FUNCTION public.save_comms_email_draft(_actor uuid, _tenant uuid, _save_id uuid, _message_id uuid, _expected_updated_at timestamp with time zone, _contact uuid, _connector uuid, _subject text, _text text, _html text, _attachments jsonb, _send_at timestamp with time zone, _approval uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\nDECLARE m public.messages%ROWTYPE; source_mailbox public.channel_connectors%ROWTYPE;\n chosen public.channel_connectors%ROWTYPE; ap public.paige_pending_approvals%ROWTYPE;\n act public.paige_actions%ROWTYPE; file jsonb; request_digest text; receipt_id uuid; prior_receipt public.paige_audit_log%ROWTYPE;\nBEGIN\n PERFORM public._comms_email_actor(_actor,_tenant);\n IF _save_id IS NULL OR (_message_id IS NULL AND _approval IS NULL) OR _expected_updated_at IS NULL OR _contact IS NULL OR _connector IS NULL\n  OR _subject IS NULL OR length(_subject) NOT BETWEEN 1 AND 200 OR length(btrim(_subject))=0\n  OR position(chr(10) in _subject)>0 OR position(chr(13) in _subject)>0\n  OR _text IS NULL OR length(_text) NOT BETWEEN 1 AND 10000 OR length(btrim(_text))=0\n  OR _html IS NULL OR length(_html) NOT BETWEEN 1 AND 100000\n  OR _attachments IS NULL OR jsonb_typeof(_attachments) IS DISTINCT FROM 'array'\n  OR jsonb_array_length(_attachments)>10 THEN\n  RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_SAVE_INVALID' USING ERRCODE='22023'; END IF;\n request_digest:=encode(sha256(convert_to(jsonb_build_object('source',_expected_updated_at,'contact',_contact,'connector',_connector,\n  'subject',_subject,'text',_text,'html',_html,'files',_attachments,'time',_send_at,'approval',_approval)::text,'UTF8')),'hex');\n PERFORM pg_advisory_xact_lock(hashtextextended(_save_id::text,32847));\n SELECT * INTO prior_receipt FROM public.paige_audit_log WHERE tenant_id=_tenant AND actor_user_id=_actor\n  AND action='comms.email_draft_saved' AND payload->>'operation_id'=_save_id::text ORDER BY created_at,id LIMIT 1;\n IF prior_receipt.id IS NOT NULL AND ((_message_id IS NOT NULL AND prior_receipt.target_id IS DISTINCT FROM _message_id)\n  OR prior_receipt.payload->>'request_digest' IS DISTINCT FROM request_digest) THEN\n  RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_SAVE_REPLAY_MISMATCH' USING ERRCODE='22023';END IF;\n\n IF _message_id IS NULL THEN\n  -- Serialize the first materialization with the existing original approval.\n  -- Never copy edited mailbox content into tenant-readable approval/action JSON.\n  SELECT * INTO ap FROM public.paige_pending_approvals WHERE id=_approval AND tenant_id=_tenant FOR UPDATE;\n  IF ap.id IS NULL OR ap.status IS DISTINCT FROM 'pending'\n   OR (ap.contact_id IS NOT NULL AND ap.contact_id IS DISTINCT FROM _contact)\n   OR ap.metadata->>'action_id' IS NULL\n   OR NOT coalesce(ap.draft_content->>'channel'='email'\n    OR (NOT (ap.draft_content ? 'channel') AND ap.draft_content->'ok'='true'::jsonb\n     AND jsonb_typeof(ap.draft_content->'draft')='object'\n     AND coalesce(ap.draft_content#>>'{draft,channel}','email')='email'),false) THEN\n   RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_OWNED_FLOW_REQUIRED' USING ERRCODE='42501';END IF;\n  SELECT * INTO act FROM public.paige_actions WHERE id::text=ap.metadata->>'action_id'\n   AND approval_id=ap.id AND tenant_id=_tenant FOR SHARE;\n  IF act.id IS NULL OR act.contact_id IS DISTINCT FROM _contact OR act.action_kind IS NULL\n   OR act.action_kind NOT IN ('owner.lead_followup','client.followup','owner.followup_email')\n   OR act.status IS NULL OR act.status NOT IN ('drafted','pending_approval')\n   OR (SELECT count(*) FROM public.paige_actions WHERE approval_id=ap.id)<>1\n   OR NOT EXISTS(SELECT 1 FROM public.paige_action_kinds WHERE slug=act.action_kind AND executor='send_via_approval')\n   OR ap.metadata ? 'governed_send' THEN\n   RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_OWNED_FLOW_REQUIRED' USING ERRCODE='42501';END IF;\n  IF prior_receipt.id IS NOT NULL THEN\n   _message_id:=prior_receipt.target_id;\n   IF ap.metadata#>>'{comms_email_draft,message_id}' IS DISTINCT FROM _message_id::text THEN\n    RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_SAVE_REPLAY_MISMATCH' USING ERRCODE='22023';END IF;\n  ELSE\n   IF ap.updated_at IS DISTINCT FROM _expected_updated_at THEN\n    RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_SOURCE_CHANGED' USING ERRCODE='40001';END IF;\n   IF ap.metadata ? 'comms_email_draft'\n    OR EXISTS(SELECT 1 FROM public.messages WHERE tenant_id=_tenant AND (action_id=act.id\n     OR meta#>>'{comms_email_binding,approval_id}'=ap.id::text)) THEN\n    RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_OWNED_FLOW_REQUIRED' USING ERRCODE='42501';END IF;\n   PERFORM public._comms_email_actor(_actor,_tenant);\n   INSERT INTO public.messages(tenant_id,contact_id,connector_id,thread_key,channel_type,direction,status,\n    recipients,sender,subject,body_text,body_html,attachments,action_id,updated_at,meta)\n   VALUES(_tenant,_contact,_connector,'contact:'||_tenant::text||':'||_contact::text,'email','outbound','draft',\n    '[]'::jsonb,'{}'::jsonb,_subject,_text,_html,'[]'::jsonb,act.id,_expected_updated_at,\n    jsonb_build_object('source','original-action-email-draft')) RETURNING id INTO _message_id;\n   UPDATE public.paige_pending_approvals SET metadata=coalesce(metadata,'{}'::jsonb)\n    ||jsonb_build_object('comms_email_draft',jsonb_build_object('message_id',_message_id))\n    WHERE id=ap.id AND tenant_id=_tenant;\n  END IF;\n END IF;\n SELECT * INTO m FROM public.messages WHERE id=_message_id AND tenant_id=_tenant FOR UPDATE;\n IF m.id IS NULL OR m.contact_id IS DISTINCT FROM _contact OR m.channel_type IS DISTINCT FROM 'email'\n  OR m.direction IS DISTINCT FROM 'outbound' OR m.status IS DISTINCT FROM 'draft' OR m.provider_message_id IS NOT NULL\n  OR m.meta ?| ARRAY['comms_email_binding','sales_invoice_binding','growth_sequence_binding','email_campaign_binding'] THEN\n  RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_SOURCE_UNAVAILABLE' USING ERRCODE='42501'; END IF;\n PERFORM 1 FROM public.clients WHERE id=_contact AND tenant_id=_tenant FOR SHARE;\n IF NOT FOUND THEN RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_SOURCE_UNAVAILABLE' USING ERRCODE='42501';END IF;\n SELECT * INTO source_mailbox FROM public.channel_connectors WHERE id=m.connector_id AND tenant_id=_tenant FOR SHARE;\n IF source_mailbox.id IS NULL OR source_mailbox.active IS DISTINCT FROM true OR source_mailbox.status IS DISTINCT FROM 'active'\n  OR source_mailbox.channel_type IS DISTINCT FROM 'email' OR NOT coalesce(source_mailbox.mailbox_class='shared_support'\n   OR (source_mailbox.mailbox_class='personal' AND source_mailbox.mailbox_owner_user_id=_actor),false) THEN\n  RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_SOURCE_UNAVAILABLE' USING ERRCODE='42501'; END IF;\n IF source_mailbox.mailbox_class='personal' AND _connector IS DISTINCT FROM m.connector_id THEN\n  RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_OWNED_FLOW_REQUIRED' USING ERRCODE='42501'; END IF;\n SELECT * INTO chosen FROM public.channel_connectors WHERE id=_connector AND tenant_id=_tenant FOR SHARE;\n IF chosen.id IS NULL OR chosen.active IS DISTINCT FROM true OR chosen.status IS DISTINCT FROM 'active'\n  OR chosen.channel_type IS DISTINCT FROM 'email' OR NOT coalesce(chosen.mailbox_class='shared_support'\n   OR (chosen.mailbox_class='personal' AND chosen.mailbox_owner_user_id=_actor),false) THEN\n  RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_SOURCE_UNAVAILABLE' USING ERRCODE='42501'; END IF;\n IF m.action_id IS NOT NULL OR _approval IS NOT NULL THEN\n  SELECT * INTO ap FROM public.paige_pending_approvals WHERE id=_approval AND tenant_id=_tenant FOR UPDATE;\n  SELECT * INTO act FROM public.paige_actions WHERE id=m.action_id AND tenant_id=_tenant FOR SHARE;\n  IF ap.id IS NULL OR ap.status IS DISTINCT FROM 'pending' OR act.id IS NULL OR act.approval_id IS DISTINCT FROM ap.id\n   OR ap.metadata->>'action_id' IS DISTINCT FROM act.id::text OR act.contact_id IS DISTINCT FROM _contact\n   OR (ap.contact_id IS NOT NULL AND ap.contact_id IS DISTINCT FROM _contact)\n   OR (act.action_kind NOT IN ('owner.lead_followup','client.followup','owner.followup_email')\n    AND NOT coalesce(act.action_kind='comms-draft-reply' AND m.meta->>'source'='comms-draft-reply'\n      AND coalesce(act.payload->>'channel_type','email')='email',false))\n   OR act.action_kind IS NULL OR act.status IS NULL OR act.status NOT IN ('drafted','pending_approval') THEN\n   RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_OWNED_FLOW_REQUIRED' USING ERRCODE='42501'; END IF;\n END IF;\n FOR file IN SELECT value FROM jsonb_array_elements(_attachments) LOOP\n  IF jsonb_typeof(file) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(file))<>4\n   OR NOT (file ?& ARRAY['url','name','mime','size']) OR jsonb_typeof(file->'url') IS DISTINCT FROM 'string'\n   OR file->>'url' !~ ('^'||_tenant::text||'/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}-[^/]+$')\n   OR jsonb_typeof(file->'name') IS DISTINCT FROM 'string' OR length(file->>'name') NOT BETWEEN 1 AND 255\n   OR jsonb_typeof(file->'mime') IS DISTINCT FROM 'string' OR length(file->>'mime') NOT BETWEEN 1 AND 255\n   OR jsonb_typeof(file->'size') IS DISTINCT FROM 'number' OR file->>'size' !~ '^[0-9]+$'\n   OR (file->>'size')::bigint NOT BETWEEN 1 AND 10485760\n   OR NOT EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id='comms-attachments' AND o.name=file->>'url') THEN\n   RAISE EXCEPTION 'COMMS_EMAIL_ATTACHMENTS_INVALID' USING ERRCODE='22023'; END IF;\n END LOOP;\n IF (SELECT coalesce(sum((value->>'size')::bigint),0) FROM jsonb_array_elements(_attachments))>10485760 THEN\n  RAISE EXCEPTION 'COMMS_EMAIL_ATTACHMENTS_INVALID' USING ERRCODE='22023'; END IF;\n IF m.updated_at IS DISTINCT FROM _expected_updated_at OR prior_receipt.id IS NOT NULL THEN\n  IF prior_receipt.id IS NOT NULL AND m.meta#>>'{comms_draft_save,id}'=_save_id::text AND m.meta#>>'{comms_draft_save,actor}'=_actor::text\n   AND m.meta#>>'{comms_draft_save,digest}'=request_digest AND m.connector_id=_connector\n   AND m.subject=_subject AND m.body_text=_text AND m.body_html=_html AND m.attachments=_attachments\n   AND m.scheduled_for IS NOT DISTINCT FROM _send_at THEN\n   SELECT id INTO receipt_id FROM public.paige_audit_log WHERE id=(m.meta#>>'{comms_draft_save,receipt_id}')::uuid\n    AND tenant_id=_tenant AND actor_user_id=_actor AND target_id=m.id AND action='comms.email_draft_saved'\n    AND payload->>'operation_id'=_save_id::text;\n   IF receipt_id IS NULL THEN RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_SAVE_RECEIPT_UNAVAILABLE' USING ERRCODE='55000';END IF;\n   RETURN jsonb_build_object('ok',true,'outcome','draft_saved','message_id',m.id,'updated_at',m.updated_at,'receipt_id',receipt_id,'replayed',true);\n  END IF;\n  RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_SOURCE_CHANGED' USING ERRCODE='40001';\n END IF;\n receipt_id:=gen_random_uuid();\n UPDATE public.messages SET connector_id=_connector,subject=_subject,body_text=_text,body_html=_html,\n  attachments=_attachments,scheduled_for=_send_at,updated_at=clock_timestamp(),\n  sender=CASE WHEN m.connector_id=_connector THEN m.sender ELSE jsonb_build_object('address',lower(btrim(chosen.from_address))) END,\n  meta=coalesce(m.meta,'{}'::jsonb)||jsonb_build_object('comms_draft_save',jsonb_build_object('id',_save_id,'actor',_actor,'digest',request_digest,'receipt_id',receipt_id))\n WHERE id=m.id AND tenant_id=_tenant RETURNING * INTO m;\n INSERT INTO public.paige_audit_log(id,actor_user_id,actor_role,tenant_id,action,target_type,target_id,payload)\n VALUES(receipt_id,_actor,'comms:'||(SELECT role FROM public.tenant_members WHERE tenant_id=_tenant AND user_id=_actor AND status='active' AND role IN ('owner','admin') ORDER BY role LIMIT 1),\n  _tenant,'comms.email_draft_saved','message',m.id,jsonb_build_object('operation_id',_save_id,'request_digest',request_digest,'source_version',_expected_updated_at,'saved_version',m.updated_at));\n RETURN jsonb_build_object('ok',true,'outcome','draft_saved','message_id',m.id,'updated_at',m.updated_at,'receipt_id',receipt_id,'replayed',false);\nEND\n$function$\n","before_md5":"cd746abf4bae4849a2a760716b690ded"}]$action_definitions$::jsonb;
 prerequisites jsonb := $action_prerequisites$[{"acl":"{postgres=X/postgres}","owner":"postgres","definer":true,"full_md5":"421eac815ac3fbc86b90cbbd2b3461d8","settings":["search_path=pg_catalog, public"],"signature":"_lead_reply_record_send(uuid,uuid,uuid)"},{"acl":"{postgres=X/postgres}","owner":"postgres","definer":true,"full_md5":"3838aa7063844f200e6ef7e7c71c6858","settings":["search_path=pg_catalog, public"],"signature":"paige_guard_send_approval_requires_governed_send()"},{"acl":"{postgres=X/postgres,service_role=X/postgres}","owner":"postgres","definer":true,"full_md5":"910674fc5c623564b46b4bb8f0f9258d","settings":["search_path=pg_catalog, public"],"signature":"prepare_comms_email_send(uuid,uuid,uuid,uuid,text,uuid,text,text,text,text,text,jsonb,jsonb,timestamp with time zone)"},{"acl":"{postgres=X/postgres,service_role=X/postgres}","owner":"postgres","definer":true,"full_md5":"1b3d7bf95f82d6cfddcb635ff61b3f2b","settings":["search_path=pg_catalog, public"],"signature":"prepare_comms_email_send(uuid,uuid,uuid,uuid,text,uuid,text,text,text,text,text,jsonb,jsonb,timestamp with time zone,jsonb)"},{"acl":"{postgres=X/postgres,service_role=X/postgres}","owner":"postgres","definer":true,"full_md5":"348fe822a186b8b41c8fa0ae08ccbb69","settings":["search_path=pg_catalog, public"],"signature":"prepare_comms_email_send(uuid,uuid,uuid,uuid,text,uuid,text,text,text,text,text,jsonb,jsonb,timestamp with time zone,jsonb,jsonb)"},{"acl":"{postgres=X/postgres,service_role=X/postgres}","owner":"postgres","definer":true,"full_md5":"03302395a40ba59e43d2012538d2cea0","settings":["search_path=pg_catalog, public"],"signature":"read_comms_email_send_binding(uuid)"},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","owner":"postgres","definer":true,"full_md5":"95250e91aa6a5c100fe22a9b11f57678","settings":["search_path=public"],"signature":"read_message_content(uuid)"}]$action_prerequisites$::jsonb;
 item jsonb; target regprocedure; observed text;
BEGIN
 FOR item IN SELECT value FROM jsonb_array_elements(prerequisites||definitions) LOOP
  target:=to_regprocedure('public.'||(item->>'signature'));
  IF target IS NULL THEN RAISE EXCEPTION 'EXP03 saved action missing original: %',item->>'signature';END IF;
  SELECT md5(pg_get_functiondef(p.oid)) INTO observed FROM pg_proc p WHERE p.oid=target
   AND pg_get_userbyid(p.proowner)=item->>'owner' AND p.prosecdef=(item->>'definer')::boolean
   AND to_jsonb(p.proconfig)=item->'settings' AND p.proacl::text=item->>'acl';
  IF observed IS NULL OR (observed IS DISTINCT FROM item->>'full_md5' AND observed IS DISTINCT FROM item->>'before_md5')
  THEN RAISE EXCEPTION 'EXP03 saved action original drift: %',item->>'signature';END IF;
 END LOOP;
 IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='public._comms_email_actor(uuid,uuid)'::regprocedure
  AND md5(pg_get_functiondef(oid))='ff1a928247c3d00c8641b639dacb7fb9'
  AND pg_get_userbyid(proowner)='postgres' AND prosecdef
  AND proconfig=ARRAY['search_path=pg_catalog, public']::text[]
  AND proacl::text='{postgres=X/postgres,service_role=X/postgres}') THEN
  RAISE EXCEPTION 'EXP03 saved action original actor drift';END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(definitions) LOOP
  target:=to_regprocedure('public.'||(item->>'signature'));
  IF md5(pg_get_functiondef(target)) IS DISTINCT FROM item->>'full_md5' THEN EXECUTE item->>'definition';END IF;
 END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(prerequisites||definitions) LOOP
  target:=to_regprocedure('public.'||(item->>'signature'));
  IF target IS NULL OR NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=target
   AND md5(pg_get_functiondef(p.oid))=item->>'full_md5' AND pg_get_userbyid(p.proowner)=item->>'owner'
   AND p.prosecdef=(item->>'definer')::boolean AND to_jsonb(p.proconfig)=item->'settings' AND p.proacl::text=item->>'acl')
  THEN RAISE EXCEPTION 'EXP03 saved action final readback drift: %',item->>'signature';END IF;
 END LOOP;
END $exp03_saved_action$;
